// "Offline support": show the last response when the network fails
Future<List<Item>> loadItems() async {
  try {
    final items = await api.fetchItems();
    await cache.save(items); // overwrites edits made offline
    return items;
  } catch (_) {
    return cache.load();
  }
}

Future<void> checkItem(String id) async {
  try {
    await api.check(id);
  } catch (_) {
    pendingRetries.add(id); // in memory: gone after process death
  }
}

// Reads come only from the local database
Stream<List<Item>> watchItems() => db.watchItems();

// The change and its queue entry commit together
Future<void> checkItem(String id) => db.transaction(() async {
      await db.markChecked(id);
      await db.enqueue(Op(id: newOpId(), itemId: id, kind: 'check'));
    });

// Runs on start, on reconnect, on resume and on push
Future<void> sync() async {
  for (final op in await db.pendingOps()) {
    await api.send(op); // throws when offline: retry later
    await db.dequeue(op.id); // the server ignores an op.id it has seen
  }
  final changes = await api.changesSince(await db.cursor());
  await db.applyServerChanges(changes); // skips rows with pending ops
}
